package com.mustafakoceerr.tilepdf.testing

import android.net.Uri
import androidx.test.platform.app.InstrumentationRegistry
import com.mustafakoceerr.tilepdf.core.pdf.PdfDocument
import com.mustafakoceerr.tilepdf.core.pdf.PdfDocumentOpener
import kotlinx.coroutines.Dispatchers
import java.io.File

/**
 * PDFs bundled in the test APK's assets (generated by
 * tools/generate_test_pdfs.py). The app under test can't read the test
 * APK's assets, so each is copied into the app's cache and opened by URI,
 * the same way SAF documents are.
 */
object TestAssets {

    private val instrumentation get() = InstrumentationRegistry.getInstrumentation()

    fun uri(name: String): Uri {
        val file = File(instrumentation.targetContext.cacheDir, name)
        instrumentation.context.assets.open(name).use { input ->
            file.outputStream().use { input.copyTo(it) }
        }
        return Uri.fromFile(file)
    }

    fun uriString(name: String): String = uri(name).toString()

    /** Opens [name] for rendering; the caller must close it. */
    suspend fun openDocument(name: String): PdfDocument =
        PdfDocumentOpener(instrumentation.targetContext, Dispatchers.IO.limitedParallelism(1)).open(uri(name))
}
